function renderBrowse(req, res) {
  const items = cache.get('browse:' + req.params.category);
  res.render('browse', {
    items,
    // teaser badge added this quarter: "as low as $X"
    lowestPrice: items.length ? Math.min(...items.map(i => i.price)) : null,
  });
}

module.exports = { renderBrowse };
